css:
.sl-cta-split { font-family: var(--smartlearn-body-font, inherit); }
.sl-cta-split .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-split .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-cta-split .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }

.sl-cta-split .sl-split-pane {
    padding: clamp(3rem, 6vw, 5.5rem) clamp(1.5rem, 4vw, 4rem);
}
.sl-cta-split .sl-split-inner { max-width: 400px; }
.sl-cta-split .sl-split-right {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-cta-split .sl-split-right-title {
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-cta-split .sl-split-right-subtitle {
    color: var(--smartlearn-btn-text, #ffffff);
    opacity: 0.9;
}
.sl-cta-split .sl-btn-outline {
    color: var(--smartlearn-primary);
    border: 2px solid var(--smartlearn-primary);
    background-color: transparent;
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-cta-split .sl-btn-outline:hover,
.sl-cta-split .sl-btn-outline:focus-visible {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-cta-split .sl-btn-solid {
    background-color: var(--smartlearn-bg) !important;
    color: var(--smartlearn-text) !important;
    border: 2px solid transparent !important;
    transition: background-color 0.2s ease, color 0.2s ease;
}
.sl-cta-split .sl-btn-solid:hover,
.sl-cta-split .sl-btn-solid:focus-visible {
    background-color: var(--smartlearn-card-bg) !important;
    color: var(--smartlearn-text) !important;
}
.sl-cta-split .sl-btn-outline:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-cta-split .sl-btn-solid:focus-visible {
    outline: 2px solid var(--smartlearn-btn-text, #ffffff);
    outline-offset: 2px;
}
@media (min-width: 768px) {
    .sl-cta-split .sl-split-left {
        border-inline-end: 1px solid var(--smartlearn-card-border);
    }
}
@media (max-width: 767.98px) {
    .sl-cta-split .sl-split-left {
        border-block-end: 1px solid var(--smartlearn-card-border);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-split .sl-btn-outline,
    .sl-cta-split .sl-btn-solid { transition: none; }
}
